fn pad2(x: i32, y: i32, v: i32, rgb: i32, sc: i32) {
    if v < 10 {
        host::display::draw_number(x, y, 0, rgb, sc);
        host::display::draw_number(x + sc * 8, y, v, rgb, sc);
    } else {
        host::display::draw_number(x, y, v, rgb, sc);
    }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let total: i32 = t / 60 + 9 * 3600 + 41 * 60;
    let hh: i32 = (total / 3600) % 24;
    let mm: i32 = (total / 60) % 60;
    let ss: i32 = total % 60;
    host::display::clear(0x050510);
    let sc: i32 = 4;
    let dw: i32 = sc * 8;
    let y: i32 = h / 2 - sc * 4;
    let x0: i32 = w / 2 - (dw * 3 + 24);
    pad2(x0, y, hh, 0xffffff, sc);
    pad2(x0 + dw * 2 + 24, y, mm, 0xffffff, sc);
    pad2(x0 + dw * 4 + 48, y, ss, 0xffffff, sc);
    if (t / 30) % 2 == 0 {
        host::display::fill_rect(x0 + dw * 2 + 8, y + sc * 2, 6, 6, 0xffffff);
        host::display::fill_rect(x0 + dw * 2 + 8, y + sc * 6, 6, 6, 0xffffff);
        host::display::fill_rect(x0 + dw * 4 + 32, y + sc * 2, 6, 6, 0xffffff);
        host::display::fill_rect(x0 + dw * 4 + 32, y + sc * 6, 6, 6, 0xffffff);
    }
    host::display::draw_string(x0, y + sc * 10, "LOCAL TIME", 0x606060, 1);
    host::display::present();
}
